  --border-error:  #f0516b;
  --text-primary:  #e8eaf0;
  --text-secondary:#9299b0;
  --text-label:    #c5c9db;
  --accent:        #6b7cff;
  --accent-hover:  #8b9bff;
  --error:         #f0516b;
  --success:       #3dd68c;
  --required:      #f0516b;
}

html {
  font-size: 100%;
}

body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100dvh;
  display: grid;
  place-items: center;
  padding: 2rem 1rem;
}

/* ── Skip link ───────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: 0 0 6px 6px;
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top 0.15s;
}

.skip-link:focus {
  top: 0;
}

/* ── Visually hidden (screen-reader only) ────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Card ────────────────────────────────────────────────────────── */
.form-container {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: clamp(1.5rem, 5vw, 2.5rem);
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: clamp(1.25rem, 3vw, 1.6rem);
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.375rem;
}

.form-intro {
  color: var(--text-secondary);
  font-size: 0.875rem;
  margin-bottom: 1.75rem;
}

/* ── Status banner ───────────────────────────────────────────────── */
.form-status {
  border-radius: 6px;
  font-size: 0.9rem;
  font-weight: 500;
}

.form-status:not(:empty) {
  padding: 0.75rem 1rem;
  margin-bottom: 1.25rem;
}

.form-status.is-success {
  background: rgba(61, 214, 140, 0.12);
  border: 1px solid var(--success);
  color: var(--success);
}

.form-status.is-error {
  background: rgba(240, 81, 107, 0.1);
  border: 1px solid var(--error);
  color: var(--error);
}

/* ── Form fields ─────────────────────────────────────────────────── */
form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-label);
}

.required-marker {
  color: var(--required);
  margin-left: 0.2em;
}

.optional-label {
  font-weight: 400;
  color: var(--text-secondary);
  font-size: 0.85em;
}

input {
  background: var(--bg-input);
  border: 1.5px solid var(--border);
  border-radius: 6px;
  color: var(--text-primary);
  font-size: 1rem;
  font-family: inherit;
  padding: 0.625rem 0.875rem;
  width: 100%;
  transition: border-color 0.15s, box-shadow 0.15s;
  -webkit-appearance: none;
  appearance: none;
}

input::placeholder {
  color: var(--text-secondary);
}

input:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(107, 124, 255, 0.25);
}

input[aria-invalid="true"] {
  border-color: var(--border-error);
}

input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(240, 81, 107, 0.25);
}

/* ── Helper & error text ─────────────────────────────────────────── */
.field-help {
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

.field-error {
  font-size: 0.8125rem;
  color: var(--error);
  font-weight: 500;
}

.field-error[hidden] {
  display: none;
}

/* ── Submit button ───────────────────────────────────────────────── */
.submit-btn {
  background: var(--accent);
  border: none;
  border-radius: 6px;
  color: #fff;
  cursor: pointer;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  margin-top: 0.25rem;
  padding: 0.75rem 1.5rem;
  transition: background-color 0.15s, box-shadow 0.15s;
  width: 100%;
}

.submit-btn:hover {
  background: var(--accent-hover);
}

.submit-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(107, 124, 255, 0.5);
}

.submit-btn:active {
  opacity: 0.9;
}

/* ── Forced colors (Windows high-contrast) ───────────────────────── */
@media (forced-colors: active) {
  input {
    border: 2px solid ButtonText;
    background: Field;
    color: FieldText;
  }
  input:focus {
    outline: 2px solid Highlight;
    box-shadow: none;
  }
  .submit-btn {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
    forced-color-adjust: none;
  }
  .required-marker {
    color: MarkText;
  }
}

/* ── Reduced motion ──────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
  }
}

/* ── Reflow / narrow viewports ───────────────────────────────────── */
@media (max-width: 320px) {
  .form-container {
    border-radius: 0;
    border-left: none;
    border-right: none;
  }
}
