  'use strict';

  const form = document.getElementById('contact-form');
  const statusBanner = document.getElementById('form-status');

  const fields = {
    'full-name': {
      el: document.getElementById('full-name'),
      errorEl: document.getElementById('full-name-error'),
      validate(val) {
        if (!val.trim()) return 'Error: Full name is required.';
        return null;
      },
    },
    email: {
      el: document.getElementById('email'),
      errorEl: document.getElementById('email-error'),
      validate(val) {
        if (!val.trim()) return 'Error: Email address is required.';
        // Basic RFC-compatible check
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val.trim())) {
          return 'Error: Enter a valid email address, like name@example.com.';
        }
        return null;
      },
    },
  };

  function setFieldError(field, message) {
    field.el.setAttribute('aria-invalid', 'true');
    field.errorEl.textContent = message;
    field.errorEl.removeAttribute('hidden');
  }

  function clearFieldError(field) {
    field.el.removeAttribute('aria-invalid');
    field.errorEl.textContent = '';
    field.errorEl.setAttribute('hidden', '');
  }

  function validateAll() {
    const errors = [];
    for (const key of Object.keys(fields)) {
      const field = fields[key];
      const message = field.validate(field.el.value);
      if (message) {
        setFieldError(field, message);
        errors.push(field.el);
      } else {
        clearFieldError(field);
      }
    }
    return errors;
  }

  // Clear field error as user corrects input (only after the form has been submitted once)
  let submitted = false;

  Object.values(fields).forEach((field) => {
    field.el.addEventListener('input', () => {
      if (!submitted) return;
      const message = field.validate(field.el.value);
      if (message) {
        setFieldError(field, message);
      } else {
        clearFieldError(field);
      }
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    submitted = true;

    // Clear previous status
    statusBanner.textContent = '';
    statusBanner.className = 'form-status';

    const errorFields = validateAll();

    if (errorFields.length > 0) {
      // Focus the first invalid field
      errorFields[0].focus();

      statusBanner.textContent =
        `Please fix ${errorFields.length} error${errorFields.length > 1 ? 's' : ''} before sending.`;
      statusBanner.classList.add('is-error');
      return;
    }

    // All valid — simulate successful submission
    const data = {
      fullName: document.getElementById('full-name').value.trim(),
      email: document.getElementById('email').value.trim(),
      phone: document.getElementById('phone').value.trim(),
    };

    // Reset form state
    form.reset();
    submitted = false;
    Object.values(fields).forEach(clearFieldError);

    statusBanner.textContent = 'Your message has been sent. We\'ll be in touch soon.';
    statusBanner.classList.add('is-success');
  });
}());
